mapper.select:
SELECT um.user_id ,um.user_nm ,um.birth_enc ,um.tel_num_enc ,um.email ,um.dept_nm ,um.weight ,um.height ,um.gender ,um.blood_type ,um.user_profile ,(SELECT ARRAY_TO_STRING(ARRAY_AGG(concat(umg2.user_nm,' ',umg2.tel_num_enc)),', ') FROM guardian_mapping_info gi LEFT JOIN user_mng umg2 ON gi.guardian_seq = umg2.user_seq WHERE gi.user_seq_fk = um.user_seq) AS guardian_nm ,(SELECT cast(array_to_json(array_agg(row_to_json(t))) as varchar) FROM ( SELECT gi.guardian_seq, gi.guardian_id, umg.user_nm, umg.tel_num_enc FROM guardian_mapping_info gi LEFT JOIN user_mng umg ON gi.guardian_seq = umg.user_seq WHERE gi.user_seq_fk = um.user_seq ) t) as guardian ,dm.user_nm AS doctor_nm ,dm.dept_nm AS doctor_dept ,di.doctor_seq AS doctor_seq ,dm.user_id AS doctor_id FROM user_mng um LEFT JOIN USER_AUTH_INFO ua ON ua.USER_SEQ = um.USER_SEQ LEFT JOIN doctor_mapping_info di ON di.user_seq_fk = um.user_seq LEFT JOIN user_mng dm ON di.doctor_seq = dm.user_seq
and ua.user_role_fk = #{userRoleFk} and um.user_id = #{userId}
and um.user_pw_enc = #{userPwEnc}

