UPDATE user_mng
SET upt_dt = now()
, upt_id = #{userId}
, user_nm = #{userNm}
, email = #{email}
, tel_num_enc = #{telNumEnc}
, birth_enc = #{birthEnc}

    , dept_nm = #{deptNm}

, height = #{height}
, weight = #{weight}
, gender = #{gender}
, blood_type = #{bloodType}
WHERE user_id = #{userId}

UPDATE user_mng
SET upt_dt = now()
  ,upt_id = #{userId}
  ,user_pw_enc = #{newUserPwEnc}
WHERE user_id = #{userId}
  and user_pw_enc = #{userPwEnc}

mapper.insert:

    select user_seq from user_mng um where um.user_id = #{userId}

INSERT INTO healthcare.doctor_mapping_info
(user_seq_fk, user_id_fk, doctor_seq, doctor_id, reg_id)
VALUES(#{userSeq}, #{userId}, #{doctorSeq}, #{doctorId}, #{userId})
ON CONFLICT (user_seq_fk, doctor_seq)
DO UPDATE
SET
doctor_seq = #{doctorSeq}
, doctor_id = #{doctorId}
, upt_dt = now()
, upt_id = #{userId}

mapper.select:
SELECT COUNT(*) AS rownum FROM
healthcare.guardian_mapping_info gmi INNER JOIN user_mng um ON gmi.guardian_seq = um.user_seq WHERE um.user_id = #{userId}
healthcare.doctor_mapping_info dmi INNER JOIN user_mng um ON dmi.doctor_seq = um.user_seq WHERE um.user_id = #{userId}

SELECT a.*, b.* FROM
guardian_mapping_info a INNER JOIN user_mng um ON a.guardian_seq = um.user_seq AND um.user_id = #{userId}
doctor_mapping_info a INNER JOIN user_mng um ON a.doctor_seq = um.user_seq AND um.user_id = #{userId}
LEFT OUTER JOIN user_mng b ON a.user_seq_fk = b.user_seq
